 }
diff --git a/test/config.test.js b/test/config.test.js
index 0ef0b7d..591606d 100644
--- a/test/config.test.js
+++ b/test/config.test.js
@@ -17,3 +17,28 @@ test("nested objects merge key by key", () => {
 		level: "info",
 	});
 });
+
+test("plain objects merge at multiple depths without changing inputs", () => {
+	const defaults = { server: { tls: { enabled: true, port: 443 }, host: "localhost" } };
+	const overrides = { server: { tls: { port: 8443 } } };
+	const beforeDefaults = structuredClone(defaults);
+	const beforeOverrides = structuredClone(overrides);
+	assert.deepEqual(mergeConfig(defaults, overrides), {
+		server: { tls: { enabled: true, port: 8443 }, host: "localhost" },
+	});
+	assert.deepEqual(defaults, beforeDefaults);
+	assert.deepEqual(overrides, beforeOverrides);
+});
+
+test("non-object overrides replace nested defaults whole", () => {
+	for (const value of [["c"], null, "disabled", 42, false, undefined]) {
+		assert.deepEqual(mergeConfig({ option: { enabled: true } }, { option: value }), { option: value });
+	}
+	assert.deepEqual(mergeConfig({ tags: ["a", "b"] }, { tags: ["c"] }), { tags: ["c"] });
+});
+
+test("a plain object replaces a non-object default", () => {
+	assert.deepEqual(mergeConfig({ server: null }, { server: { port: 9090 } }), {
+		server: { port: 9090 },
+	});
+});
